import { test as base, expect } from '@playwright/test';
import { readFileSync } from 'node:fs';

const DAY = 864e5;
export const iso = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const parse = s => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); };
export const daysAgo = n => { const t = new Date(); return iso(new Date(t.getFullYear(), t.getMonth(), t.getDate() - n)); };

// Made-up six-week GZCLP log (generated by the app's own sample-data builder).
export function fixture() {
  return JSON.parse(readFileSync(new URL('./fixtures/sample-backup.json', import.meta.url), 'utf8')).data;
}

// Move every date in a log so the newest workout lands `lastDaysAgo` days before today.
export function shiftLog(data, lastDaysAgo) {
  const d = structuredClone(data);
  const last = d.sessions.map(s => s.date).sort().at(-1);
  const delta = Math.round((parse(daysAgo(lastDaysAgo)) - parse(last)) / DAY);
  const mv = s => s && iso(new Date(parse(s).getTime() + delta * DAY + 12 * 3600e3));
  for (const s of d.sessions) {
    s.date = mv(s.date);
    for (const k of ['createdAt', 'startedAt', 'endedAt']) if (s[k]) s[k] += delta * DAY;
  }
  for (const p of d.plans) if (p.startedAt) p.startedAt = mv(p.startedAt);
  for (const b of d.bodyweights || []) b.date = mv(b.date);
  return d;
}

// Put a log into the browser before the app loads (only on the first navigation, so reloads keep what the app saved).
export async function seed(page, data) {
  await page.addInitScript(json => {
    if (!sessionStorage.getItem('il-seeded')) { localStorage.setItem('ironledger.v1', json); sessionStorage.setItem('il-seeded', '1'); }
  }, JSON.stringify(data));
}

export async function open(page, tab, sub) {
  await page.locator(`[data-act=tab][data-tab=${tab}]`).click();
  if (sub) await page.locator(`[data-act=sub][data-s=${sub}]`).click();
}

export async function finishWorkout(page) {
  const done = page.locator('[data-act=done]');
  for (let i = 0; i < await done.count(); i++) if (await done.nth(i).getAttribute('aria-pressed') !== 'true') await done.nth(i).click();
  await page.locator('[data-act=finish]').click();
  const yes = page.locator('#modal:not([hidden]) [data-act=cYes]');
  if (await yes.count()) await yes.click();
  await expect(page.locator('#view')).toContainText('done');
}

export const view = page => page.locator('#view');

// Every test fails if the page throws, and Google Fonts is skipped so runs don't depend on the network.
export const test = base.extend({
  page: async ({ page }, use) => {
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.route(/fonts\.(googleapis|gstatic)\.com/, r => r.abort());
    await use(page);
    expect(errors, 'uncaught errors in the page').toEqual([]);
  }
});
export { expect };
